import json

task = json.load(open('task.json'))
parts = task['parts']

# Compute geometry for each part
info = {}
for p in parts:
    idx = p['index']
    sx, sy, sz = p['size_m']
    tx, ty, tz = p['target_position']
    bottom_z = tz - sz/2
    top_z = tz + sz/2
    x_min, x_max = tx - sx/2, tx + sx/2
    y_min, y_max = ty - sy/2, ty + sy/2
    info[idx] = {
        'size': (sx, sy, sz),
        'target': (tx, ty, tz),
        'bottom_z': bottom_z,
        'top_z': top_z,
        'x_range': (x_min, x_max),
        'y_range': (y_min, y_max)
    }

# Determine support relationships
# Part j supports part i if:
#   - j.top_z ≈ i.bottom_z (within tolerance)
#   - x ranges overlap (non-empty intersection with positive width)
#   - y ranges overlap (non-empty intersection with positive width)

def ranges_overlap(r1, r2):
    lo = max(r1[0], r2[0])
    hi = min(r1[1], r2[1])
    return (hi - lo) > 1e-6  # strictly positive overlap

TOL = 1e-4
supports = {}  # supports[i] = set of parts that support i
for i, ii in info.items():
    supports[i] = set()
    for j, jj in info.items():
        if i == j:
            continue
        if abs(jj['top_z'] - ii['bottom_z']) < TOL:
            if ranges_overlap(jj['x_range'], ii['x_range']) and ranges_overlap(jj['y_range'], ii['y_range']):
                supports[i].add(j)

# Topological sort (Kahn's algorithm)
in_degree = {i: len(s) for i, s in supports.items()}
dependents = {i: set() for i in info}
for i, s in supports.items():
    for j in s:
        dependents[j].add(i)

from collections import deque
queue = deque([i for i, d in in_degree.items() if d == 0])
order = []
while queue:
    # Sort for determinism
    queue = deque(sorted(queue))
    node = queue.popleft()
    order.append(node)
    for dep in dependents[node]:
        in_degree[dep] -= 1
        if in_degree[dep] == 0:
            queue.append(dep)

if len(order) != len(info):
    print("ERROR: cycle detected!")
else:
    print("Valid topological order:")
    for idx in order:
        s = info[idx]
        print(f"  Part {idx}: target={s['target']}, bottom_z={s['bottom_z']:.3f}, supported_by={supports[idx]}")

# Group by level
levels = {}
for i in order:
    level = 0
    if supports[i]:
        level = 1 + max(levels.get(j, 0) for j in supports[i])
    levels[i] = level

print("\nBy level:")
for lvl in sorted(set(levels.values())):
    parts_at_level = [i for i in order if levels[i] == lvl]
    print(f"  Level {lvl}: parts {parts_at_level}")

